WITH prepared AS (SELECT jsonb_array_elements('[{"slug":"agriculture-value-added-share","intro":"نسبة القيمة المضافة من أنشطة الزراعة والغابات والصيد إلى إجمالي الناتج المحلي وفق تقسيم الحسابات القومية. تشير أحدث قيمة منشورة لليمن إلى 28.75 % من الناتج المحلي في سنة القياس 2018، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"توضح الوزن النسبي للقطاع الزراعي والأنشطة المتصلة به في تكوين الناتج، وتكمل قراءة الوظائف والأمن الغذائي.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (27.39 % من الناتج المحلي)، و2004 (12.42 % من الناتج المحلي)، و2018 (28.75 % من الناتج المحلي). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"حصة الناتج لا تساوي نسبة السكان العاملين بالقطاع أو نسبة الاكتفاء الغذائي. وقد ترتفع لأن بقية القطاعات تقلصت، لا لأن الإنتاج الزراعي زاد. السلسلة تقف عند سنة 2018، فلا تصف الوضع الراهن في 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات الزراعة والحسابات القومية. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات الزراعة والحسابات القومية — بيانات المؤشر","url":"https://data.worldbank.org/indicator/NV.AGR.TOTL.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"air-transport-freight","intro":"حجم الشحن الجوي المنقول مرجحاً بمسافة النقل، ويُقاس بملايين الأطنان-كيلومتر لا بوزن الشحنات وحده. تشير أحدث قيمة منشورة لليمن إلى 49.73 مليون طن كيلومتر في سنة القياس 2023، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يوضح النشاط اللوجستي للطيران في نقل البضائع ويمكن مقارنته بحركة الركاب والتجارة الجوية.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (11.5 مليون طن كيلومتر)، و2004 (59.74 مليون طن كيلومتر)، و2023 (49.73 مليون طن كيلومتر). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"انخفاض المؤشر لا يخبرنا وحده بعدد الرحلات أو قيم السلع أو أسعار النقل، وقد يتأثر بالمسافة والمسارات وتعريف الناقلات الداخلة. تخص أحدث قيمة سنة 2023، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/IS.AIR.GOOD.MT.K1?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"air-transport-passengers","intro":"عدد الركاب المنقولين جواً كما يُحصيهم المصدر وفق نطاق شركات الطيران أو الرحلات المشمولة بالسلسلة. تشير أحدث قيمة منشورة لليمن إلى 618,613 مسافر في سنة القياس 2023، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد على متابعة نشاط النقل الجوي واتصال البلاد جواً ودراسة تعافي خدمات السفر في حدود التعريف المعتمد.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (671,100 مسافر)، و2006 (1,162,316 مسافر)، و2023 (618,613 مسافر). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"عدد الركاب ليس بالضرورة عدد الأشخاص الفريدين؛ المسافر في رحلتين قد يُحسب أكثر من مرة. ولا يحدد الوجهات المفتوحة أو الجداول المتاحة حالياً. تخص أحدث قيمة سنة 2023، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/IS.AIR.PSGR?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"basic-drinking-water-services","intro":"نسبة السكان الذين يستخدمون على الأقل خدمة مياه شرب أساسية وفق تصنيف الرصد المشترك للصحة العالمية واليونيسف، الذي يميز المصدر المحسّن وزمن جمع المياه. تشير أحدث قيمة منشورة لليمن إلى 75.04 % من السكان في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يوضح مدى الوصول إلى مصادر مياه محسنة على المستوى الوطني ويؤسس لمناقشة احتياجات الأسر وتفاوت ظروف تزويد المياه.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 2000 (40.1 % من السكان)، و2012 (54.99 % من السكان)، و2024 (75.04 % من السكان). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يعني أن المياه متاحة على مدار اليوم أو أنها خالية من التلوث في كل وقت. ولا يساوي معيار المياه «المدارة بأمان» أو الوصول إلى شبكة منزلية. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.H2O.BASW.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"basic-sanitation-services","intro":"حصة السكان الذين يستخدمون مرافق صرف صحي محسّنة وغير مشتركة مع أسر أخرى وفق تعريف خدمة الصرف الصحي الأساسية. تشير أحدث قيمة منشورة لليمن إلى 63.08 % من السكان في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يضيء جانباً من ظروف النظافة والصحة البيئية في المنازل ويُقرأ مع المياه والأمراض وحالة البنية التحتية.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 2000 (43.42 % من السكان)، و2012 (53 % من السكان)، و2024 (63.08 % من السكان). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يقيس التخلص الآمن من الحمأة أو المعالجة الكاملة لمياه الصرف، ولا يثبت أن الشبكات تعمل دون تسرب. يختلف عن خدمة الصرف «المدارة بأمان». تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.STA.BASS.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"cereal-yield","intro":"متوسط كمية الحبوب المنتجة لكل هكتار من المساحة المحصودة، وهو مقياس إنتاجية الأرض لا إجمالي المحصول الوطني. تشير أحدث قيمة منشورة لليمن إلى 768.7 كيلوغرام للهكتار في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد على قراءة إنتاجية محاصيل الحبوب ومدى تغير الكفاءة الزراعية، مع مراعاة المياه والبذور والطقس وأنواع المحاصيل.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (907.7 كيلوغرام للهكتار)، و2007 (1,020 كيلوغرام للهكتار)، و2024 (768.7 كيلوغرام للهكتار). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"ارتفاع الغلة لا يعني بالضرورة ارتفاع إجمالي الإنتاج إذا تقلصت مساحة الحصاد. تتأثر بالتركيب المحصولي والظروف المناخية وقد تكون قيمة وطنية متوسطة. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات الزراعة والحسابات القومية. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات الزراعة والحسابات القومية — بيانات المؤشر","url":"https://data.worldbank.org/indicator/AG.YLD.CREL.KG?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"child-stunting-prevalence","intro":"نسبة الأطفال دون الخامسة الذين يقل طولهم بالنسبة للعمر عن الحد المعتمد للنمو الصحي ضمن تعريف القياس الدولي. تشير أحدث قيمة منشورة لليمن إلى 48.5 % من الأطفال دون الخامسة في سنة القياس 2022، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يكشف بعداً من سوء التغذية المزمن وتأخر النمو، ويرتبط تفسيره بالتغذية والأمراض والمياه وصحة الأم والطفل.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1991 (50.4 % من الأطفال دون الخامسة)، و2005 (57 % من الأطفال دون الخامسة)، و2022 (48.5 % من الأطفال دون الخامسة). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يشير إلى عدد الأطفال الجائعين في يوم القياس ولا يساوي الهزال الحاد أو نقص الوزن وحده. وتعتمد المقارنة على المسوح والفئة السكانية وتاريخها. تخص أحدث قيمة سنة 2022، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.STA.STNT.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"container-port-traffic","intro":"الحاويات التي تعاملت معها الموانئ ضمن القياس الدولي بوحدة الحاوية المكافئة لعشرين قدماً، وليس عدد السفن. تشير أحدث قيمة منشورة لليمن إلى 380,000 حاوية مكافئة لعشرين قدما في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يضيء نشاط تداول الحاويات ودور الموانئ في سلاسل الإمداد، ويمكن مقارنته بتدفقات التجارة والقدرة اللوجستية.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 2010 (390,000 حاوية مكافئة لعشرين قدما)، و2017 (334,693 حاوية مكافئة لعشرين قدما)، و2024 (380,000 حاوية مكافئة لعشرين قدما). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"وحدة TEU تقيس حجم الحاويات القياسي ولا تساوي وزن البضائع أو قيمتها المالية، ولا تعني أن كل منفذ يعمل بطاقته القصوى. تختلف عمليات العبور وإعادة الشحن. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/IS.SHP.GOOD.TU?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"crop-production-index","intro":"مؤشر لحجم الإنتاج المحصولي محسوب نسبة إلى فترة الأساس 2014–2016 التي تساوي 100؛ وليس كمية بالطن. تشير أحدث قيمة منشورة لليمن إلى 116.39 مؤشر 2014-2016 = 100 في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يسمح بمتابعة تغير الإنتاج النسبي للمحاصيل عبر السنوات على مقياس ثابت، بعيداً عن اختلاف وحدات المحاصيل.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (50.56 مؤشر 2014-2016 = 100)، و2007 (94.2 مؤشر 2014-2016 = 100)، و2024 (116.39 مؤشر 2014-2016 = 100). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"قيمة 120 تعني مستوى مؤشر أعلى من أساسه بـ20% تقريباً، ولا تعني 120 طناً أو 120% من احتياج اليمن الغذائي. تركيبة المؤشر وأوزانه تؤثر على القراءة. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات الزراعة والحسابات القومية. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات الزراعة والحسابات القومية — بيانات المؤشر","url":"https://data.worldbank.org/indicator/AG.PRD.CROP.XD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"current-health-expenditure-share-gdp","intro":"ما يُنفق على خدمات الرعاية الصحية الجارية مقارنة بالناتج المحلي، وفق مفهوم الحسابات الصحية الوطنية، دون افتراض شموله كل الاستثمارات الرأسمالية. تشير أحدث قيمة منشورة لليمن إلى 9.7 % من الناتج المحلي في سنة القياس 2023، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يوضح الوزن المالي للخدمات الصحية مقارنة بحجم الاقتصاد، ويتيح طرح أسئلة عن التمويل العام والخاص والمساعدات والنفقات المباشرة للأسر.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 2000 (4.67 % من الناتج المحلي)، و2011 (4.77 % من الناتج المحلي)، و2023 (9.7 % من الناتج المحلي). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"ارتفاع حصة الإنفاق قد ينتج عن انخفاض الناتج لا زيادة حقيقية في الخدمة. النسبة لا تقيس جودة العلاج أو عدالة توزيع التمويل. تخص أحدث قيمة سنة 2023، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.XPD.CHEX.GD.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"dpt-immunization-rate","intro":"حصة الأطفال بعمر 12 إلى 23 شهراً الذين تلقوا الجرعات المقررة للقاح الدفتيريا والسعال الديكي والكزاز وفق تعريف برنامج التحصين ومصدر البيانات. تشير أحدث قيمة منشورة لليمن إلى 42 % من الأطفال بعمر 12 إلى 23 شهرا في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يُستخدم لفهم الوصول إلى خدمات تطعيم الطفولة الأساسية والقدرة على استمرار الجرعات الدورية. يساعد ربطه بخدمات الرعاية الأولية وسلاسل تبريد اللقاحات في دراسة الفجوات.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (84 % من الأطفال بعمر 12 إلى 23 شهرا)، و2007 (79 % من الأطفال بعمر 12 إلى 23 شهرا)، و2024 (42 % من الأطفال بعمر 12 إلى 23 شهرا). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يعني أن الطفل حصل على جميع التطعيمات الأخرى أو أن كل منطقة وصلت إلى المستوى نفسه، ولا يقيس الإصابات بالأمراض مباشرة. قد تعتمد القيمة على تقارير وطنية وتقديرات دولية. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.IMM.IDPT?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"electric-power-losses","intro":"حصة الطاقة الكهربائية المفقودة في النقل والتوزيع من الإنتاج المحتسب وفق تعريف سلسلة بيانات الكهرباء. تشير أحدث قيمة منشورة لليمن إلى 27.63 % من إنتاج الكهرباء في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"توضح جانباً من كفاءة البنية الكهربائية وتفيد في مناقشة إدارة الشبكات والتقنيات والصيانة. يحتاج تفسيرها إلى فهم النطاق الجغرافي للكهرباء الداخلة في القياس.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (11.55 % من إنتاج الكهرباء)، و2007 (25.42 % من إنتاج الكهرباء)، و2024 (27.63 % من إنتاج الكهرباء). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا تقيس ساعات الانقطاع أو مقدار استهلاك المنازل، وقد تشمل خسائر فنية وغير فنية بحسب المصدر. ولا ينبغي خلطها بنسبة السكان الذين تصلهم الكهرباء. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - قاعدة الوصول إلى الكهرباء SDG7. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - قاعدة الوصول إلى الكهرباء SDG7 — بيانات المؤشر","url":"https://data.worldbank.org/indicator/EG.ELC.LOSS.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"fixed-telephone-subscriptions","intro":"عدد الاشتراكات النشطة في خدمة الهاتف الثابت قياساً بكل 100 من السكان، وليس عدد الأشخاص الذين يستخدمون الهاتف بالفعل. تشير أحدث قيمة منشورة لليمن إلى 1.9 لكل 100 شخص في سنة القياس 2022، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد في فهم تحول وسائل الاتصال والبنية التحتية الثابتة مع توسع الاتصالات المتنقلة والإنترنت.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (0.9 لكل 100 شخص)، و2005 (3.96 لكل 100 شخص)، و2022 (1.9 لكل 100 شخص). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"قد تمتلك جهة واحدة عدة خطوط، وقد يستخدم عدة أشخاص خطاً واحداً؛ لذلك لا يساوي نسبة الأفراد المتصلين. لا يحدد جودة الخدمة أو توفرها في الأحياء. تخص أحدث قيمة سنة 2022، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/IT.MLT.MAIN.P2?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"hospital-beds-per-thousand","intro":"عدد أسرّة المستشفيات الداخلة في إحصاءات المصدر مقابل كل ألف من السكان، وليس عدد الأسرّة المتاحة في كل لحظة. تشير أحدث قيمة منشورة لليمن إلى 0.46 لكل 1000 شخص في سنة القياس 2023، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد على تقدير الطاقة السريرية للنظام الصحي مقارنة بالحجم السكاني، ويمكن قراءته مع عدد الأطباء وتوزيع المؤسسات الصحية.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (0.84 لكل 1000 شخص)، و2010 (0.6 لكل 1000 شخص)، و2023 (0.46 لكل 1000 شخص). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يبيّن إن كانت الأسرّة تعمل ومجهزة أو يسهل الوصول إليها، ولا يسرد إشغال المستشفيات أو اختلاف المحافظات. زيادة العدد لا تثبت جودة العلاج. تخص أحدث قيمة سنة 2023، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.MED.BEDS.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"internet-users-share","intro":"نسبة الأفراد الذين استخدموا الإنترنت خلال الفترة المرجعية التي تعتمدها الجهة الناشرة، وليس عدد الاشتراكات الهاتفية. تشير أحدث قيمة منشورة لليمن إلى 17.49 % من السكان في سنة القياس 2019، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد على فهم حجم المشاركة الرقمية وإمكانية الوصول إلى المعرفة والعمل والخدمات الإلكترونية.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (0 % من السكان)، و2006 (1.25 % من السكان)، و2019 (17.49 % من السكان). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يقيس السرعة أو جودة الاتصال أو كلفته أو عدد الساعات المستفادة منه. وما لم تتوفر سنة أحدث، لا يمثل الرقم الانتشار في 2026. السلسلة تقف عند سنة 2019، فلا تصف الوضع الراهن في 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/IT.NET.USER.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"life-expectancy-at-birth","intro":"متوسط السنوات المتوقع أن يعيشها مولود افتراضي إذا تعرض طوال حياته لأنماط الوفيات حسب الأعمار في سنة القياس. تشير أحدث قيمة منشورة لليمن إلى 69.44 سنة في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"مؤشر تلخيصي لمستويات البقاء والصحة عبر الأعمار، ويُستفاد منه في قراءة التحولات السكانية وطول العمر ضمن السياق الوطني.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (58.53 سنة)، و2007 (66.23 سنة)، و2024 (69.44 سنة). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"ليس متوسط أعمار كل من توفوا فعلياً في السنة، ولا عمراً مضموناً للمولود أو تقييماً منفرداً لجودة المستشفيات. يتأثر بتقديرات الوفيات والأزمات وتحديث النماذج. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: الأمم المتحدة - بيانات السكان عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"الأمم المتحدة - بيانات السكان عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SP.DYN.LE00.IN?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"livestock-production-index","intro":"مؤشر لكمية الإنتاج الحيواني وفق منهجية تجمع منتجات مختارة وتستخدم متوسط الفترة 2014–2016 أساساً يساوي 100. تشير أحدث قيمة منشورة لليمن إلى 125.57 مؤشر 2014-2016 = 100 في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يتيح مقارنة مسار الإنتاج الحيواني عبر الوقت دون جمع مقاييس مختلفة مثل اللحوم والحليب والبيض في وحدة وزن واحدة.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (29.76 مؤشر 2014-2016 = 100)، و2007 (61.05 مؤشر 2014-2016 = 100)، و2024 (125.57 مؤشر 2014-2016 = 100). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"المؤشر ليس عدد رؤوس الماشية ولا كمية اللحوم بالطن، ولا يصف صحة القطعان أو سعر المنتجات. تغيير المنهجية أو الأوزان قد يؤثر على المقارنات. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات الزراعة والحسابات القومية. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات الزراعة والحسابات القومية — بيانات المؤشر","url":"https://data.worldbank.org/indicator/AG.PRD.LVSK.XD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"maternal-mortality-ratio","intro":"عدد وفيات الأمهات المرتبطة بالحمل والولادة أو ما يليهما وفق الفترة والتعريف الإحصائي مقابل كل 100 ألف ولادة حية. تشير أحدث قيمة منشورة لليمن إلى 118 لكل 100 ألف ولادة حية في سنة القياس 2023، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد في تقييم مخاطر الحمل والوصول إلى خدمات الولادة الآمنة والرعاية الطارئة والإحالة، ويُستخدم لتحديد الحاجة إلى تدخلات صحية موثقة.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (359 لكل 100 ألف ولادة حية)، و2006 (171 لكل 100 ألف ولادة حية)، و2023 (118 لكل 100 ألف ولادة حية). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يتضمن كل وفيات النساء في سن الإنجاب، ولا يعادل احتمال وفاة المرأة خلال حياتها. تقدير الظاهرة في البيئات ضعيفة التسجيل يحمل عدم يقين. تخص أحدث قيمة سنة 2023، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.STA.MMRT?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"mineral-rents-share-gdp","intro":"قيمة الريع الاقتصادي التقديري للمعادن المشمولة قياساً بالناتج المحلي، بحسب تعريف الموارد والتكاليف المستخدم. تشير أحدث قيمة منشورة لليمن إلى 0 % من الناتج المحلي في سنة القياس 2018، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يوضح ما تقوله إحصاءات الريع عن مساهمة الموارد المعدنية بالنسبة للاقتصاد، مع ضرورة التمييز بين الاستخراج والمعالجة والتصدير.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (0 % من الناتج المحلي)، و2004 (0 % من الناتج المحلي)، و2018 (0 % من الناتج المحلي). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"ليس قيمة احتياطيات المعادن تحت الأرض، ولا الإيرادات الضريبية للمناجم أو مجموع صادرات التعدين. وقد لا يغطي كل أنشطة التعدين الحرفي. السلسلة تقف عند سنة 2018، فلا تصف الوضع الراهن في 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — بيانات المؤشر","url":"https://data.worldbank.org/indicator/NY.GDP.MINR.RT.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"mobile-cellular-subscriptions","intro":"عدد الاشتراكات الخلوية النشطة أو المسجلة وفق تعريف المصدر لكل 100 ساكن؛ وهو عدّ للشرائح والاشتراكات لا للأشخاص الفريدين. تشير أحدث قيمة منشورة لليمن إلى 50.89 لكل 100 شخص في سنة القياس 2023، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يبيّن اتساع الاشتراكات الهاتفية مقارنة بحجم السكان ويساعد في دراسة خدمات الاتصالات الرقمية والتحول عن الهاتف الثابت.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (0 لكل 100 شخص)، و2006 (12.65 لكل 100 شخص)، و2023 (50.89 لكل 100 شخص). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"قد يستخدم شخص عدة شرائح أو لا يكون الاشتراك مستخدماً فعلياً على الدوام. ويمكن أن يتجاوز العدد 100 دون أن يعني أن جميع المواطنين يمتلكون هاتفاً. تخص أحدث قيمة سنة 2023، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/IT.CEL.SETS.P2?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"oil-rents-share-gdp","intro":"تقدير الريع الاقتصادي الناجم عن استخراج النفط كنسبة من الناتج المحلي، وفق الفرق بين قيمة الإنتاج وتكاليفه في منهجية المصدر. تشير أحدث قيمة منشورة لليمن إلى 4.82 % من الناتج المحلي في سنة القياس 2018، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد على فهم حجم الاعتماد النسبي على المورد النفطي في الاقتصاد وتقلب إيراداته مقارنة بالنشاط الكلي.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (28.51 % من الناتج المحلي)، و2004 (34.06 % من الناتج المحلي)، و2018 (4.82 % من الناتج المحلي). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"الريع المقدر ليس إجمالي إيرادات الخزانة من النفط ولا صافي أرباح شركة معينة. ويتأثر بالأسعار العالمية والكميات والتكلفة وحجم الناتج. السلسلة تقف عند سنة 2018، فلا تصف الوضع الراهن في 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات الاقتصاد والتمويل. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات الاقتصاد والتمويل — بيانات المؤشر","url":"https://data.worldbank.org/indicator/NY.GDP.PETR.RT.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"physicians-per-thousand","intro":"عدد الأطباء المشمولين في بيانات الكوادر الصحية لكل ألف نسمة وفق نطاق الإحصاء وتعريف الطبيب المستخدم. تشير أحدث قيمة منشورة لليمن إلى 0.1 لكل 1000 شخص في سنة القياس 2023، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يعطي مؤشراً عاماً لكثافة القوة الطبية بالنسبة للسكان، ويكمل دراسة تغطية الرعاية الأولية والتخصصات ونظام الإحالة.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (0.01 لكل 1000 شخص)، و2008 (0.28 لكل 1000 شخص)، و2023 (0.1 لكل 1000 شخص). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يحدد عدد الأطباء المزاولين يومياً أو توزيعهم الجغرافي أو ساعات عملهم، وقد تختلف منهجية إحصاء الممارسين عن المرخصين. لا يستنتج منه توافر طبيب بعينه. تخص أحدث قيمة سنة 2023، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.MED.PHYS.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"renewable-energy-consumption-share","intro":"نسبة الطاقة المتجددة من إجمالي الاستهلاك النهائي للطاقة، وتشمل أنواع الطاقة الداخلة في تعريف المصدر الدولي. تشير أحدث قيمة منشورة لليمن إلى 3.7 % من إجمالي الاستهلاك النهائي للطاقة في سنة القياس 2021، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"تساعد على دراسة مزيج الطاقة المستهلكة ومكانة المصادر المتجددة فيه، مع ربطه بالقطاع الكهربائي والنقل والوقود المنزلي.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (1.8 % من إجمالي الاستهلاك النهائي للطاقة)، و2005 (0.7 % من إجمالي الاستهلاك النهائي للطاقة)، و2021 (3.7 % من إجمالي الاستهلاك النهائي للطاقة). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا تساوي نسبة المنازل المزودة بألواح شمسية أو الكهرباء المنتجة من الشمس فقط؛ فقد تشمل طاقة حيوية تقليدية. ولا تعكس تلقائياً الاستدامة البيئية لكل مصدر. تخص أحدث قيمة سنة 2021، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - قاعدة الوصول إلى الكهرباء SDG7. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - قاعدة الوصول إلى الكهرباء SDG7 — بيانات المؤشر","url":"https://data.worldbank.org/indicator/EG.FEC.RNEW.ZS?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"road-traffic-mortality-rate","intro":"معدل وفيات حوادث الطرق لكل 100 ألف نسمة خلال سنة قياس، وفق تقديرات سلامة الطرق وتعريف الوفاة المرتبطة بالحادث. تشير أحدث قيمة منشورة لليمن إلى 29.4 لكل 100 ألف شخص في سنة القياس 2019، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد في تقدير العبء الإنساني لحوادث المرور، ومناقشة أنظمة السلامة والإسعاف وجودة الطرق.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 2000 (21.9 لكل 100 ألف شخص)، و2009 (23 لكل 100 ألف شخص)، و2019 (29.4 لكل 100 ألف شخص). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يمثل عدد كل الحوادث أو الإصابات غير القاتلة، وقد تختلف التقديرات عن سجلات الشرطة والمستشفيات. ولا يحدد الأماكن الأخطر دون بيانات مكانية مستقلة. السلسلة تقف عند سنة 2019، فلا تصف الوضع الراهن في 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.STA.TRAF.P5?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"total-fisheries-production","intro":"إجمالي كمية الإنتاج من الصيد وتربية الأحياء المائية الداخلة في التصنيف الإحصائي للمصدر، مقاسة بالأطنان المترية. تشير أحدث قيمة منشورة لليمن إلى 152,440 طن متري في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد على فهم الحجم المادي لنشاط الثروة السمكية وأهميته للغذاء وسلاسل التبريد والتصنيع والتجارة.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (77,310 طن متري)، و2007 (180,216 طن متري)، و2024 (152,440 طن متري). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يساوي قيمة المبيعات أو صادرات الأسماك، ولا يكشف الاستدامة البيئية أو نوعية الأنواع أو التوزيع بين سواحل اليمن. وقد تكون هناك كميات غير مرصودة. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات الزراعة والحسابات القومية. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات الزراعة والحسابات القومية — بيانات المؤشر","url":"https://data.worldbank.org/indicator/ER.FSH.PROD.MT?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"tuberculosis-incidence","intro":"العدد المقدر لحالات السل الجديدة والانتكاسات خلال سنة لكل 100 ألف نسمة، وفق تعريف وبرنامج الترصد المستخدمين. تشير أحدث قيمة منشورة لليمن إلى 40 لكل 100 ألف شخص في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"يساعد في متابعة عبء السل والحاجة إلى التشخيص المبكر واستمرارية العلاج وتتبع المخالطين، خصوصاً عندما تكون الخدمات الصحية تحت ضغط.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 2000 (94 لكل 100 ألف شخص)، و2012 (47 لكل 100 ألف شخص)، و2024 (40 لكل 100 ألف شخص). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"العدد المقدر لا يساوي الحالات المؤكدة بالمختبر فقط، وقد تتغير التقديرات عند تحديث بيانات الترصد. لا يسمح المؤشر وحده بقياس نجاح العلاج أو انتشار العدوى في محافظة محددة. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.TBS.INCD?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"under-five-mortality-rate","intro":"احتمال وفاة مولود حي قبل بلوغ الخامسة، معبّراً عنه لكل ألف ولادة حية وفق تقديرات الوفيات الخاصة بالأطفال. تشير أحدث قيمة منشورة لليمن إلى 38.1 لكل 1000 ولادة حية في سنة القياس 2024، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"من أهم مؤشرات صحة الطفولة، لأنه يتيح دراسة تحديات الوقاية والتغذية والتطعيم والرعاية الطبية بصورة متكاملة.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 1990 (125.2 لكل 1000 ولادة حية)، و2007 (63.4 لكل 1000 ولادة حية)، و2024 (38.1 لكل 1000 ولادة حية). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يُفسر وحده سبب الوفاة أو يحدد تأثير حرب أو مرض بعينه. وهو معدل/احتمال مقدر وليس إجمالي عدد الأطفال المتوفين. تخص أحدث قيمة سنة 2024، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: منظمة الصحة العالمية وشركاؤها عبر البنك الدولي. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"منظمة الصحة العالمية وشركاؤها عبر البنك الدولي — بيانات المؤشر","url":"https://data.worldbank.org/indicator/SH.DYN.MORT?locations=YE"}],"reviewed_on":"2026-10-27"},{"slug":"urban-population-living-in-slums","intro":"حصة سكان المناطق الحضرية الذين يعيشون في مساكن تفتقر إلى واحد أو أكثر من شروط السكن الملائم الداخلة في تعريف المؤشر. تشير أحدث قيمة منشورة لليمن إلى 44.2 % من سكان الحضر في سنة القياس 2022، وفق السلسلة الإحصائية المعتمدة.","why_it_matters":"مهم لفهم احتياجات تحسين السكن الحضري والمياه والصرف والمساحات الآمنة، ولتوجيه الأسئلة عن نوعية البنية الأساسية.","historical_context":"تعرض قاعدة 967 هذه النقاط الفعلية: 2000 (63.81 % من سكان الحضر)، و2010 (50.7 % من سكان الحضر)، و2022 (44.2 % من سكان الحضر). تُقرأ هذه السنوات في سياق السلسلة الكاملة دون افتراض اتجاه موحد بينها أو إسناد أسباب غير موثقة.","limitations":"لا يصف بالضرورة كل حي غير رسمي أو قيمة الأرض فيه، ولا يشمل السكان الريفيين في المقام. التعريف الإحصائي للعشوائيات لا يساوي حكماً قانونياً على السكان. تخص أحدث قيمة سنة 2022، ولا تعني أن الظروف بقيت كما هي حتى 2026. ينبغي الرجوع إلى تعريف المنتج الأصلي قبل الاستشهاد بالرقم أو مقارنته بمؤشر مختلف.","source_notes":"سلسلة مصدرها المسجل في 967: البنك الدولي - مؤشرات البنية التحتية والاتصالات. أرقام السنوات مأخوذة من قيم المؤشر الوطني المحفوظة في 967 كما كانت عند مراجعة 27 أكتوبر 2026. بعض القيم تقديرية وقد يراجع الناشر منهجيتها؛ لم تُجر هذه القراءة إحصاءً ميدانياً جديداً.","reference_links":[{"title":"البنك الدولي - مؤشرات البنية التحتية والاتصالات — بيانات المؤشر","url":"https://data.worldbank.org/indicator/EN.POP.SLUM.UR.ZS?locations=YE"}],"reviewed_on":"2026-10-27"}]'::jsonb) AS d),
inserted AS (
 INSERT INTO public.stat_indicator_editorial(indicator_id,intro,why_it_matters,historical_context,limitations,source_notes,reference_links,reviewed_on,is_published)
 SELECT i.id,p.d->>'intro',p.d->>'why_it_matters',p.d->>'historical_context',p.d->>'limitations',p.d->>'source_notes',p.d->'reference_links',(p.d->>'reviewed_on')::date,true
 FROM prepared p JOIN public.stat_indicators i ON i.slug=p.d->>'slug' WHERE i.is_published AND i.slug<>'access-to-electricity'
 ON CONFLICT(indicator_id) DO NOTHING RETURNING indicator_id
) SELECT (SELECT count(*) FROM prepared) AS prepared,(SELECT count(*) FROM inserted) AS inserted;